eco_guide <- 
function (var1 = "var1", var2 = "var2", output = c("viewer", "console")) 
{
    output <- match.arg(output)
    v1 <- gsub("\"", "", deparse(substitute(var1)))
    v2 <- gsub("\"", "", deparse(substitute(var2)))
    lignes_guide <- c("# ==============================================================================", paste0("# GUIDE COMPLET R SERIES TEMPORELLES - PIPELINE EXAMEN (", v1, " & ", v2, ")"), "# ==============================================================================", "", "# ------------------------------------------------------------------------------", "# 0. PACKAGES & IMPORTATION", "# ------------------------------------------------------------------------------", "library(readxl)    # read_xlsx", 
        "library(urca)      # ur.df, ur.kpss, ca.jo, cajorls", "library(forecast)  # Arima, auto.arima, checkresiduals, forecast, autoplot", "library(tseries)   # jarque.bera.test", "library(lmtest)    # coeftest", "library(moments)   # skewness, kurtosis", "library(FinTS)     # ArchTest", "library(Metrics)   # mae, rmse", "library(vars)      # VARselect, VAR, causality, irf, stability, arch.test", "library(lpirfs)    # lp_lin (projections locales)", "library(tsDyn)     # VECM", "library(exuber)    # radf, radf_mc_cv, datestamp (bulles speculatives)", 
        "", "d <- read_xlsx(\"fichier.xlsx\", sheet = 1)", "d$date <- as.Date(d$date)", "", "# ------------------------------------------------------------------------------", "# 1. PREPARATION DES SERIES TEMPORELLES (ts), LOG & GRAPHIQUES (Q1 - Q2)", "# ------------------------------------------------------------------------------", "# Mensuel : frequency = 12 | Trimestriel : frequency = 4 | Annuel : frequency = 1", paste0(v1, " <- ts(log(d$x1), start = c(1990, 1), frequency = 4)"), paste0(v2, " <- ts(log(d$x2), start = c(1990, 1), frequency = 4)"), 
        "", "# Decroissance lente ACF + pic PACF lag 1 => non stationnaire I(1)", paste0("plot(", v1, "); acf(", v1, "); pacf(", v1, ")"), paste0("plot(", v2, "); acf(", v2, "); pacf(", v2, ")"), "", "# ------------------------------------------------------------------------------", "# 2. RACINE UNITAIRE (ADF SEQUENTIEL + KPSS) & STATIONNARISATION (Q3)", "# ------------------------------------------------------------------------------", "# ADF (H0 : racine unitaire) -> rejet H0 si tau < seuil 5% (-3.43 / -2.88 / -1.95)", 
        "# Si non-rejet RU : t-stat tt = 2.79, const = 2.54 (DF) | Si rejet RU : 1.96 (Normale)", paste0("summary(adf3_", v1, " <- ur.df(", v1, ", \"trend\", 8, \"AIC\"))"), paste0("summary(adf2_", v1, " <- ur.df(", v1, ", \"drift\", 8, \"AIC\"))"), paste0("summary(adf1_", v1, " <- ur.df(", v1, ", \"none\",  8, \"AIC\"))"), "", paste0("summary(adf3_", v2, " <- ur.df(", v2, ", \"trend\", 8, \"AIC\"))"), paste0("summary(adf2_", v2, " <- ur.df(", v2, ", \"drift\", 8, \"AIC\"))"), paste0("summary(adf1_", 
            v2, " <- ur.df(", v2, ", \"none\",  8, \"AIC\"))"), "", "# KPSS (H0 : stationnaire) -> seuils 5% : tau = 0.146 (tendance) | mu = 0.463 (const)", paste0("summary(ur.kpss(", v1, ", type = \"tau\"))"), paste0("summary(ur.kpss(", v2, ", type = \"tau\"))"), "", "# Stationnarisation par difference premiere (taux de croissance) & verification I(0)", paste0("d_", v1, " <- diff(", v1, ")"), paste0("d_", v2, " <- diff(", v2, ")"), "", paste0("summary(ur.df(d_", v1, ", \"trend\", 8, \"AIC\"))"), 
        paste0("summary(ur.df(d_", v1, ", \"drift\", 8, \"AIC\"))"), paste0("summary(ur.df(d_", v1, ", \"none\",  8, \"AIC\"))"), paste0("summary(ur.kpss(d_", v1, ", type = \"mu\"))"), "", paste0("summary(ur.df(d_", v2, ", \"trend\", 8, \"AIC\"))"), paste0("summary(ur.df(d_", v2, ", \"drift\", 8, \"AIC\"))"), paste0("summary(ur.df(d_", v2, ", \"none\",  8, \"AIC\"))"), paste0("summary(ur.kpss(d_", v2, ", type = \"mu\"))"), "", "# ------------------------------------------------------------------------------", 
        "# 3. DETECTION DE BULLES SPECULATIVES EXPLOSIVES : EXUBER (SADF / GSADF)", "# ------------------------------------------------------------------------------", "# Sur serie en niveau ou log : H0 = racine unitaire vs H1 = comportement explosif", paste0("psy_minw(", v1, ")"), paste0("radf_", v1, " <- radf(", v1, ", lag = 1)"), paste0("mc_cv <- radf_mc_cv(n = length(", v1, "), nrep = 1000, seed = 145)"), paste0("summary(radf_", v1, ", cv = mc_cv)"), paste0("diagnostics(radf_", v1, ", cv = mc_cv)"), 
        paste0("bulle <- datestamp(radf_", v1, ", cv = mc_cv, min_duration = psy_ds(", v1, "), option = \"gsadf\")"), paste0("autoplot(radf_", v1, ", option = \"gsadf\", cv = mc_cv, min_duration = psy_ds(", v1, "))"), "", "# ------------------------------------------------------------------------------", "# 4. IDENTIFICATION, ESTIMATION & VALIDATION D'UN MODELE ARMA (Q4)", "# ------------------------------------------------------------------------------", paste0("acf(d_", v1, "); pacf(d_", v1, ")"), 
        paste0("auto.arima(d_", v1, ", seasonal = FALSE)"), "", "# include.mean = TRUE si constante significative dans M2 de l'ADF", paste0("arma <- arima(d_", v1, ", order = c(1, 0, 1), include.mean = TRUE)"), "coeftest(arma)                                     # significativite coeffs (p < 0.05)", "autoplot(arma)                                     # racines inverses < 1 (cercle unite)", "checkresiduals(arma)                               # Ljung-Box : p > 0.05 => bruit blanc", "r <- arma$residuals", 
        "jarque.bera.test(r)                                # p > 0.05 => normalite des residus", "skewness(r); kurtosis(r)                           # proches de 0 et 3", "ArchTest(r, lags = 4)                              # lags=4 (trim.) ou 12 (mens.) ; p > 0.05 => homosc.", "", "# ------------------------------------------------------------------------------", "# 5. PREVISIONS EN NIVEAU & EVALUATION HORS-ECHANTILLON RMSE / MAE (Q5)", "# ------------------------------------------------------------------------------", 
        "# 5a. Previsions a h = 1, 2, 3 + retour a l'indice brut initial (d$x1 avant log)", "dprev <- forecast(arma, h = 3)", "dprev$mean", "x1_prev <- tail(d$x1, 1) * exp(cumsum(dprev$mean))", "x1_prev", "", "# 5b. Evaluation hors-echantillon sur les 4 dernieres periodes de la serie stationnaire", paste0("n <- length(d_", v1, ")"), paste0("fit <- arima(d_", v1, "[1:(n - 4)], order = c(1, 0, 1), include.mean = TRUE)"), "prev <- forecast(fit, h = 4)$mean", paste0("obs  <- d_", v1, "[(n - 3):n]"), 
        paste0("naif <- d_", v1, "[(n - 4):(n - 1)]"), "rmse(obs, prev); mae(obs, prev)", "rmse(obs, naif); mae(obs, naif)", "", "# ------------------------------------------------------------------------------", "# 6. MODELE VAR & LES 5 DIAGNOSTICS OBLIGATOIRES (Q6)", "# ------------------------------------------------------------------------------", "# Placer en 1er la variable qui cause l'autre (coherence Cholesky Q8)", paste0("Y <- cbind.data.frame(d_", v1, ", d_", v2, ")"), paste0("colnames(Y) <- c(\"d_", 
            v1, "\", \"d_", v2, "\")"), "VARselect(Y, lag.max = 8, type = \"const\")$selection", "v <- VAR(Y, p = 2, type = \"const\")", "summary(v)", "", "# Les 5 tests de validation du VAR :", "roots(v)                                           # tous < 1 => stabilite dynamique", "serial.test(v)                                     # p > 0.05 => pas d'autocorrelation", "normality.test(v)                                  # p > 0.05 => normalite multivariee", "arch.test(v)                                       # p > 0.05 => pas d'effet ARCH multivarie", 
        "plot(stability(v))                                 # CUSUM dans les bandes critiques a 5%", "", "# ------------------------------------------------------------------------------", "# 7. CAUSALITE AU SENS DE GRANGER (Q7)", "# ------------------------------------------------------------------------------", paste0("g1 <- causality(v, cause = \"d_", v1, "\")$Granger"), "g1$statistic; qf(0.95, g1$parameter[1], g1$parameter[2])", paste0("g2 <- causality(v, cause = \"d_", v2, "\")$Granger"), "g2$statistic; qf(0.95, g2$parameter[1], g2$parameter[2])", 
        "", "# ------------------------------------------------------------------------------", "# 8. IMPULSION-REPONSE : IRF CHOLESKY & PROJECTIONS LOCALES DE JORDA (Q8)", "# ------------------------------------------------------------------------------", "# Attention : l'argument d'horizon est n.ahead (et non h)", "i <- irf(v, n.ahead = 12, ci = 0.90)", "plot(i)", "", "# Conversion numerique obligatoire avant lp_lin (evite l'erreur dplyr::lag sur <ts>)", "Yd <- data.frame(lapply(as.data.frame(Y), as.numeric))", 
        "lp <- lp_lin(Yd, lags_endog_lin = 2, trend = 0, hor = 12, confint = 1.645, shock_type = 0)", "plot(lp)", "", "# ------------------------------------------------------------------------------", "# 9. COINTEGRATION DE JOHANSEN & MODELE VECM (Q9 - Series I(1) en niveau/log)", "# ------------------------------------------------------------------------------", paste0("Z <- cbind.data.frame(", v1, ", ", v2, ")"), paste0("colnames(Z) <- c(\"", v1, "\", \"", v2, "\")"), "VARselect(Z, lag.max = 8, type = \"const\")$selection   # donne le retard K en niveau", 
        "jo <- ca.jo(Z, type = \"trace\", ecdet = \"const\", K = 2)", "summary(jo)", "", "# Si r = 0 rejete et r <= 1 non rejete => r = 1 relation de cointegration", "# Le VAR en differences est mal specifie -> estimer le VECM avec lag = K - 1 :", "vecm <- VECM(Z, lag = 1, estim = \"ML\", LRinclude = \"const\")", "summary(vecm)", "plot_ECT(vecm)")
    script_txt <- paste(lignes_guide, collapse = "\n")
    if (output == "console") {
        cat(script_txt, "\n")
    }
    else {
        html_file <- tempfile(fileext = ".html")
        html_content <- paste0("<!DOCTYPE html><html><head><meta charset='utf-8'>", "<title>Guide Examen EcoTS : ", v1, " & ", v2, "</title>", "<style>", "body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; margin: 16px; background: #f8f9fa; color: #212529; }", "h2 { color: #0d6efd; border-bottom: 2px solid #0d6efd; padding-bottom: 6px; font-size: 1.2em; }", "table { border-collapse: collapse; width: 100%; margin-bottom: 16px; font-size: 0.85em; background: #fff; }", 
            "th, td { border: 1px solid #dee2e6; padding: 6px 8px; text-align: left; }", "th { background: #e9ecef; }", "pre { background: #1e1e1e; color: #d4d4d4; padding: 14px; border-radius: 6px; overflow-x: auto; font-size: 0.85em; line-height: 1.45; }", "</style></head><body>", "<h2>Pipeline Complet Examen (<code>", v1, "</code> & <code>", v2, "</code>)</h2>", "<table><tr><th>Test / Etape</th><th>Fonction R</th><th>H0</th><th>Regle de decision (5%)</th></tr>", "<tr><td>ADF</td><td><code>ur.df(urca)</code></td><td>Racine unitaire (non stat.)</td><td>Stat &lt; val. critique (-3.43 / -2.88 / -1.95) &rArr; Stationnaire</td></tr>", 
            "<tr><td>KPSS</td><td><code>ur.kpss(urca)</code></td><td>Stationnarite</td><td>Stat &gt; val. critique (0.146 tau / 0.463 mu) &rArr; Non stat.</td></tr>", "<tr><td>Bulles</td><td><code>radf(exuber)</code></td><td>Racine unitaire (vs explosive)</td><td>Stat &gt; val. critique MC &rArr; Bulle speculative</td></tr>", "<tr><td>Ljung-Box</td><td><code>checkresiduals</code></td><td>Absence d'autocorrelation</td><td><b>p &gt; 0.05</b> &rArr; Bruit blanc valide</td></tr>", "<tr><td>Jarque-Bera</td><td><code>jarque.bera.test</code></td><td>Normalite des residus</td><td><b>p &gt; 0.05</b> &rArr; Normalite validee</td></tr>", 
            "<tr><td>ARCH-LM</td><td><code>ArchTest(FinTS)</code></td><td>Homoscedasticite</td><td><b>p &gt; 0.05</b> &rArr; Pas d'effet ARCH</td></tr>", "<tr><td>Granger</td><td><code>causality(vars)</code></td><td>Absence de causalite</td><td><b>p &lt; 0.05</b> (ou F &gt; F_crit) &rArr; Causalite</td></tr>", "<tr><td>Johansen</td><td><code>ca.jo(urca)</code></td><td>Rang de cointegration &le; r</td><td>Trace &gt; val. critique &rArr; Cointegration (VECM)</td></tr></table>", "<pre><code>", gsub("<", 
                "&lt;", gsub(">", "&gt;", script_txt)), "</code></pre>", "</body></html>")
        writeLines(html_content, html_file)
        viewer <- getOption("viewer")
        if (!is.null(viewer) && rstudioapi::isAvailable()) {
            viewer(html_file)
        }
        else {
            utils::browseURL(html_file)
        }
    }
    invisible(script_txt)
}
